/**
 * Workspace-membership checks for Agent SDK Slack agents.
 * Mirrors backend `isExternalSlackUser` (cloud-agent/slack/externalChannelPolicy).
 */
import { fetchSlackUserInfo, resetSlackUserInfoCache } from "./user-info.js";
/** Pure classifier over a `users.info` user object. Fails open to external. */
export function classifySlackUserExternality(args) {
    const { slackTeamId, user } = args;
    if (user.is_stranger === true ||
        user.is_restricted === true ||
        user.is_ultra_restricted === true) {
        return true;
    }
    return (user.team_id !== undefined &&
        user.team_id !== slackTeamId &&
        !(user.enterprise_user?.teams ?? []).includes(slackTeamId));
}
const classified = new Map();
export function resetExternalSenderCache() {
    classified.clear();
    resetSlackUserInfoCache();
}
/** Lookup + classify. Empty userId / API failure → external. Hits cache. */
export async function isExternalSlackSender(args) {
    if (args.userId === "") {
        return true;
    }
    const key = `${args.slackTeamId}:${args.userId}`;
    const cached = classified.get(key);
    if (cached !== undefined) {
        return cached;
    }
    try {
        const user = await fetchSlackUserInfo({
            botToken: args.botToken,
            userId: args.userId,
        });
        if (user === undefined) {
            return true;
        }
        const external = classifySlackUserExternality({
            slackTeamId: args.slackTeamId,
            user: user,
        });
        classified.set(key, external);
        return external;
    }
    catch {
        return true;
    }
}
